/* Figma room and add-on pickers; changes remain draft until Apply. */
const pickerCatalog=[{id:'catering',title:'Group Catering',rate:55,rule:'Per Person',delivery:'Every Day'},...[
 ['shuttle','Airport Shuttle',35,'Per Item','Arrival day'],['coffee','Coffee and Tea Break',6.5,'Per Person','Every Day'],['lunch','Boxed Lunch',11.5,'Per Person','Every Day'],['dinner','Banquet Dinner',28,'Per Person','Every Day'],['av','AV and Livestream Package',250,'Per Item','Every Day']
].map(([id,title,rate,rule,delivery])=>({id,title,rate,rule,delivery}))];
let pickerDraft=null;
function pickerItems(){return [...pickerCatalog,...(wizard.customAddons||[])];}
function beginPicker(kind){pickerDraft=kind==='room-picker'?wizard.rooms.map(r=>({...r})):pickerItems().map(x=>({...x,qty:x.id==='catering'?(wizard.cateringQty||wizard.guests*nights()):(wizard.extraAddons||[]).find(a=>a.id===x.id)?.qty||1,selected:x.id==='catering'?!!wizard.cateringQty:(wizard.extraAddons||[]).some(a=>a.id===x.id)}));modal=kind;renderOverlay();}
function pickerShell(title,body,footer,small=false){return '<div class="modal-backdrop"><section class="modal figma-picker '+(small?'picker-create':'')+'" role="dialog" aria-modal="true" aria-labelledby="picker-title"><button class="modal-close" data-action="picker-dismiss" aria-label="Close">×</button><header class="modal-header" id="picker-title">'+title+'</header><div class="modal-content">'+body+'<div id="picker-error" class="error"></div></div><footer class="modal-footer">'+footer+'</footer></section></div>';}
const pickerOverlayBase=renderOverlay;
renderOverlay=function(){if(!['room-picker','addon-picker','picker-create'].includes(modal))return pickerOverlayBase();document.body.style.overflow='hidden';let body,title,footer;
 if(modal==='room-picker'){title='Room Types';const r=state.request,total=pickerDraft.reduce((s,x)=>s+x.qty,0);body='<div class="row between picker-heading"><div><b>Room types for '+dates()+' · '+nights()+' nights</b><p>Requested '+(requestedRoomCount(r))+' rooms · Single '+r.single+' · Double '+r.double+' · Cabins '+(r.cabin||0)+'</p></div>'+badge('Selected '+total+' of '+(requestedRoomCount(r)))+'</div>'+table(['','ROOM TYPE','BED TYPE','ROOMS','AVAIL','MAX OCC','RATE'],pickerDraft.map((x,i)=>['<input type="checkbox" data-pick-room="'+i+'" aria-label="Select '+esc(x.type)+'" '+(x.qty?'checked':'')+'>',esc(x.type),x.bed,'<input type="number" data-pick-qty="'+i+'" aria-label="'+esc(x.type)+' quantity" min="0" max="'+x.available+'" value="'+x.qty+'">',x.available,[1,2,4,2][i],money(x.rate)]));}
 else if(modal==='addon-picker'){title='Add-ons';body='<div class="row between picker-search"><label class="field">Search<input name="picker-search" placeholder="Search for Add-ons"></label>'+button('Create New','picker-create')+'</div>'+table(['','ITEM','QTY','DELIVERY','BASE RATE','PRICE'],pickerDraft.map((x,i)=>['<input type="checkbox" data-pick-addon="'+i+'" aria-label="Select '+esc(x.title)+'" '+(x.selected?'checked':'')+'>',esc(x.title),x.qty,esc(x.delivery),money(x.rate)+' '+esc(x.rule),money(x.qty*x.rate)]));}
 else{title='Create New Add-on';body='<form id="picker-create-form" class="stack">'+field('Name','title','','text','required maxlength="100"')+textarea('Description','description','')+'<div class="grid3">'+select('Calculation rule','rule','Per Person',['Per Person','Per Item'])+field('Rate','rate',18,'number','required min="0" step="0.01"')+select('Delivery schedule','delivery','Arrival day',['Arrival day','Every Day','Departure day'])+'</div><div class="grid2">'+select('Category','category','Catering',['Catering','Transport','Equipment','Other'])+select('Tax','tax','Taxable (10%)',['Taxable (10%)','Not taxable'])+'</div>'+check('Also available in POS','pos',true)+'</form>';}
 footer=button('Cancel','picker-dismiss')+button(modal==='picker-create'?'Save add-on':'Apply',modal==='picker-create'?'picker-save-new':'picker-save','primary');$('#overlay').innerHTML=pickerShell(title,body,footer,modal==='picker-create');};
const pickerHandleBase=handle;
handle=function(a,el){if(['room-picker','addon-picker'].includes(a)){captureWizard();if(a==='room-picker'&&!wizard.rooms.some(r=>r.type==='Accessible Double Room'))wizard.rooms.push({type:'Accessible Double Room',bed:'Double',qty:0,rate:140,available:2});beginPicker(a);return;}
 if(a==='picker-dismiss'||a==='close-modal'&&['room-picker','addon-picker','picker-create'].includes(modal)){modal=modal==='picker-create'?'addon-picker':'wizard';renderOverlay();return;}
 if(a==='picker-create'){modal='picker-create';renderOverlay();return;}
 if(a==='picker-save-new'){const f=$('#picker-create-form');if(!f.reportValidity())return;const v=Object.fromEntries(new FormData(f)),x={...v,id:'custom-'+Date.now(),rate:Number(v.rate),qty:1,selected:true};wizard.customAddons=[...(wizard.customAddons||[]),x];pickerDraft.push(x);modal='addon-picker';renderOverlay();return;}
 if(a==='picker-save'){if(modal==='room-picker'){if(pickerDraft.some(x=>!Number.isInteger(x.qty)||x.qty<0||x.qty>x.available)){$('#picker-error').textContent='Enter room quantities within available inventory.';return;}wizard.rooms=pickerDraft.map(x=>({...x}));}else{const c=pickerDraft.find(x=>x.id==='catering');wizard.cateringQty=c.selected?c.qty:0;wizard.cateringRate=c.rate;wizard.extraAddons=pickerDraft.filter(x=>x.id!=='catering'&&x.selected).map(x=>({...x}));}modal='wizard';renderOverlay();return;}return pickerHandleBase(a,el);};
document.addEventListener('change',e=>{const t=e.target;if(t.dataset.pickRoom!==undefined){const x=pickerDraft[Number(t.dataset.pickRoom)];x.qty=t.checked?(x.qty||1):0;renderOverlay();}if(t.dataset.pickQty!==undefined){pickerDraft[Number(t.dataset.pickQty)].qty=Number(t.value);renderOverlay();}if(t.dataset.pickAddon!==undefined)pickerDraft[Number(t.dataset.pickAddon)].selected=t.checked;});
document.addEventListener('input',e=>{if(e.target.name==='picker-search'){const term=e.target.value.toLowerCase();$('#overlay').querySelectorAll('tbody tr').forEach(row=>row.hidden=!row.textContent.toLowerCase().includes(term));}});
const pickerTotalsBase=totals,pickerRowsBase=quoteRows,pickerWizardBase=wizardBody;
totals=function(q=state.quote||wizard){if(!q?.extraAddons?.length)return pickerTotalsBase(q);const extra=q.extraAddons.reduce((s,x)=>s+x.qty*x.rate,0),copy={...q,cateringQty:1,cateringRate:q.cateringQty*q.cateringRate+extra},t=pickerTotalsBase(copy);return {...t,addons:q.cateringQty*q.cateringRate+extra};};
quoteRows=function(q=state.quote||wizard){return [...pickerRowsBase(q),...(q.extraAddons||[]).map(x=>[esc(x.title),x.qty,'—',money(x.rate),money(x.qty*x.rate)])];};
wizardBody=function(){let html=pickerWizardBase();if(wizard.step===2&&wizard.extraAddons?.length)html=html.replace('<div id="wizard-error"',table(['ADD-ON','QTY','RATE','TOTAL'],wizard.extraAddons.map(x=>[esc(x.title),x.qty,money(x.rate),money(x.qty*x.rate)]))+'<div id="wizard-error"');return html;};
